/// <reference types="vite/client" />

declare module 'virtual:buffer-polyfill';

// Generated by the stateImagesManifest plugin in vite.config.ts from
// public/state-images/ — pools keys are "state-folder/substate" paths,
// values are public URLs of every image in that pool (sorted by filename).
// focal maps an image URL to its "x% y%" background-position (from
// focal.json, written by the review tool) so cover crops follow the
// subject instead of dead-centering.
declare module 'virtual:state-images' {
    const manifest: { pools: Record<string, string[]>; focal: Record<string, string> };
    export default manifest;
}